/** 문단 말투 보존 평가(1~5점)입니다. 참여자·문단당 하나이며 다시 매기면 덮어쓴다. */
package com.dandimate.durooduroo.scroll.domain;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="paragraph_ratings", uniqueConstraints=@UniqueConstraint(name="uk_paragraph_ratings_member", columnNames={"paragraph_id","member_id"})) public class ParagraphRating { @Id private String id; @Column(name="paragraph_id",nullable=false) private String paragraphId; @Column(name="member_id",nullable=false) private String memberId; @Column(nullable=false) private int score; @Column(nullable=false) private LocalDateTime updatedAt; protected ParagraphRating(){} private ParagraphRating(String p,String m,int s){id=UUID.randomUUID().toString();paragraphId=p;memberId=m;score=s;updatedAt=LocalDateTime.now();} public static ParagraphRating of(String paragraphId,String memberId,int score){return new ParagraphRating(paragraphId,memberId,score);} public void rate(int score){this.score=score;updatedAt=LocalDateTime.now();} public int getScore(){return score;} }
